        "Berdasarkan kesepakatan kerja sama strategis, kedua belah pihak akan melakukan kerja sama mendalam secara menyeluruh dan jangka panjang yang berpusat di sektor ritel FMCG Asia Tenggara, dan akan fokus pada tiga tugas utama untuk membangun ekosistem layanan 4PL yang lengkap."
