        "Berdasarkan teknologi kecerdasan digital rantai pasokan yang matang dari teknologi 8 meter, menggabungkan pemahaman mendalam ASC tentang lingkungan ritel Asia Tenggara, bersama-sama mengembangkan solusi 4PL untuk pengiriman bersama gudang terintegrasi yang cocok untuk pasar lokal. Solusi ini akan mewujudkan 'tiga kompetensi inti'. Pertama, manajemen intensif inventaris memungkinkan multi brand dan multi channel berbagi sumber daya gudang, mengurangi defisit inventaris dengan sinkronisasi real-time inventaris dan penempatan dinamis. Kedua, meningkatkan efisiensi logistik dan biaya transportasi dengan mengoptimalkan rute transportasi mingguan dan rencana pengiriman akhir melalui algoritma AI. Ketiga, meningkatkan efisiensi pengiriman dan transparansi data. Selain itu, langkah ini juga disesuaikan dengan karakteristik kebutuhan multibahasa, multi-moneter, dan multi-regulasi di Asia Tenggara, sehingga dapat diterapkan dengan lancar di berbagai negara dan wilayah."
